<main class="mx-auto max-w-7xl px-4 py-10"><header class="mb-8 flex flex-wrap items-end justify-between gap-4 border-b border-silver-800 pb-5"><div><p class="font-mono text-xs tracking-[.3em] text-silver-500">// CMS CONTROL NODE</p><h1 class="font-oswald text-5xl uppercase">System settings</h1></div><a href="<?php echo e(route('admin')); ?>" class="border border-silver-600 px-3 py-2 text-xs">BACK TO ADMIN</a></header><div class="grid gap-6 xl:grid-cols-2"><form method="post" action="<?php echo e(route('admin.settings.update')); ?>" enctype="multipart/form-data" class="border border-silver-700 bg-pitch-900 p-6 text-xs"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><h2 class="mb-5 font-oswald text-2xl uppercase">Website identity & SEO</h2><?php $__currentLoopData = ['site_name' => 'WEBSITE NAME', 'site_tagline' => 'HEADER TAGLINE / SLOGAN', 'seo_title' => 'SEO TITLE', 'seo_description' => 'META DESCRIPTION', 'seo_keywords' => 'KEYWORDS', 'default_jurisdiction' => 'DEFAULT JURISDICTION', 'default_designation' => 'DEFAULT DESIGNATION', 'xrp_address' => 'XRP DEPOSIT ADDRESS', 'xrp_memo' => 'XRP MEMO / DESTINATION TAG']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $key => $label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><label class="mb-3 block"><?php echo e($label); ?><input name="<?php echo e($key); ?>" value="<?php echo e($settings[$key] ?? ''); ?>" class="mt-1 w-full border border-silver-700 bg-pitch-950 p-2"></label><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?><label class="mb-3 block">FAVICON<input type="file" name="favicon" accept=".ico,.png,.svg" class="mt-1 w-full border border-silver-700 bg-pitch-950 p-2"></label><label class="mb-5 block">LOGO<input type="file" name="logo" accept="image/*" class="mt-1 w-full border border-silver-700 bg-pitch-950 p-2"></label><button class="w-full bg-white p-3 font-bold text-black">SAVE WEBSITE SETTINGS</button></form><div class="space-y-6"><section class="border border-silver-700 bg-pitch-900 p-6 text-xs"><h2 class="mb-4 font-oswald text-2xl uppercase">Assign member identity</h2><p class="mb-4 text-silver-500">Type a name, email, or citizen number. Results are limited to 10 members.</p><form method="post" action="<?php echo e(route('admin.users.identity', ['user' => 0])); ?>" id="identityAssignment" class="grid gap-2"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><input id="memberSearch" autocomplete="off" placeholder="Search member..." class="border border-silver-700 bg-pitch-950 p-2"><div id="memberResults" class="space-y-1"></div><input type="hidden" name="jurisdiction" value="<?php echo e($settings['default_jurisdiction'] ?? 'Local Community / Own Country'); ?>"><input type="hidden" name="designation" value="<?php echo e($settings['default_designation'] ?? 'Ginhawa Citizen'); ?>"><p id="selectedMember" class="text-silver-500">No member selected.</p><button class="border border-silver-500 p-2">ASSIGN IDENTITY</button></form></section><section class="border border-silver-700 bg-pitch-900 p-6 text-xs"><h2 class="mb-4 font-oswald text-2xl uppercase">Dynamic roles</h2><form method="post" action="<?php echo e(route('admin.roles.store')); ?>" class="grid gap-2"><?php echo csrf_field(); ?><input name="name" required placeholder="internal-name" class="border border-silver-700 bg-pitch-950 p-2"><input name="label" required placeholder="Display title" class="border border-silver-700 bg-pitch-950 p-2"><input name="clearance" type="number" min="1" max="5" value="1" class="border border-silver-700 bg-pitch-950 p-2"><input name="permissions" placeholder="posts.approve,users.verify" class="border border-silver-700 bg-pitch-950 p-2"><button class="border border-silver-500 p-2">CREATE ROLE</button></form><div class="mt-4 space-y-1 text-silver-400"><?php $__currentLoopData = $roles; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $role): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><p><?php echo e($role->label); ?> <span class="text-silver-600">(<?php echo e($role->name); ?>)</span></p><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></div></section><section class="border border-silver-700 bg-pitch-900 p-6 text-xs"><h2 class="mb-4 font-oswald text-2xl uppercase">Sectors & directives</h2><form method="post" action="<?php echo e(route('admin.sectors.store')); ?>" class="mb-4 grid gap-2"><?php echo csrf_field(); ?><input name="name" required placeholder="Sector name" class="border border-silver-700 bg-pitch-950 p-2"><input name="slug" required placeholder="sector-slug" class="border border-silver-700 bg-pitch-950 p-2"><textarea name="description" placeholder="Sector description" class="border border-silver-700 bg-pitch-950 p-2"></textarea><button class="border border-silver-500 p-2">ADD SECTOR</button></form><div class="mb-4 space-y-2"><?php $__empty_1 = true; $__currentLoopData = $sectors; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $sector): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); $__empty_1 = false; ?><div class="flex items-center justify-between gap-2 border border-silver-800 bg-pitch-950 p-2"><div><span class="text-white"><?php echo e($sector->name); ?></span><br><span class="text-[10px] <?php echo e($sector->requires_approval ? 'text-silver-500' : 'text-silver-400'); ?>"><?php echo e($sector->requires_approval ? 'COUNCIL APPROVAL REQUIRED' : 'NO COUNCIL APPROVAL'); ?></span></div><form method="post" action="<?php echo e(route('admin.sectors.approval', $sector)); ?>" class="flex items-center gap-2"><?php echo csrf_field(); ?> <?php echo method_field('PATCH'); ?><label class="flex items-center gap-1 text-[10px] text-silver-400"><input type="checkbox" name="requires_approval" value="1" <?php if($sector->requires_approval): echo 'checked'; endif; ?> onchange="this.form.submit()"> REQUIRES APPROVAL</label></form></div><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); if ($__empty_1): ?><div class="text-silver-600">No sectors yet.</div><?php endif; ?></div><form method="post" action="<?php echo e(route('admin.directives.store')); ?>" class="grid gap-2"><?php echo csrf_field(); ?><input name="title" required placeholder="Directive title" class="border border-silver-700 bg-pitch-950 p-2"><textarea name="body" required placeholder="Directive text" class="border border-silver-700 bg-pitch-950 p-2"></textarea><button class="border border-silver-500 p-2">ADD DIRECTIVE</button></form></section></div></div></main>
+<?php $__env->startPush('scripts'); ?><script>const memberSearch=document.getElementById('memberSearch'),memberResults=document.getElementById('memberResults'),identityAssignment=document.getElementById('identityAssignment'),selectedMember=document.getElementById('selectedMember');let searchTimer;memberSearch.addEventListener('input',()=>{clearTimeout(searchTimer);const query=memberSearch.value.trim();memberResults.innerHTML='';if(query.length<2)return;searchTimer=setTimeout(()=>fetch('<?php echo e(route('admin.users.search')); ?>?q='+encodeURIComponent(query),{headers:{Accept:'application/json'}}).then(response=>response.json()).then(users=>{memberResults.innerHTML=users.map(user=>`<button type="button" class="block w-full border border-silver-800 bg-pitch-950 p-2 text-left text-xs hover:border-white" data-id="${user.id}" data-name="${user.name}" data-citizen="${user.citizen_number||''}">${user.name} // ${user.citizen_number||user.email}</button>`).join('');memberResults.querySelectorAll('button').forEach(button=>button.onclick=()=>{identityAssignment.action='<?php echo e(url('/admin/users')); ?>/'+button.dataset.id+'/identity';selectedMember.textContent='Selected: '+button.dataset.name+' // '+button.dataset.citizen;memberResults.innerHTML='';memberSearch.value=button.dataset.name})}).catch(()=>{memberResults.innerHTML='<p class="text-red-300">Member search unavailable.</p>'})},250)})</script><?php $__env->stopPush(); ?>
